using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
internal sealed partial class ModernWorkspace {
 void EditDofusOverlay(){if(store.Value.settings.PrivacyMode)return;StackPanel body,actions;var w=Dialog("Personnaliser l’overlay Dofus",out body,out actions,610);DofusToolsUi.Options(body,actions,store,()=>w.Close(),()=>{Refresh();UpdateDofusOverlay();},Ink,Muted);ShowWindow(w);}
 void EditDofusStepNotes(TougliStep step){if(step==null||store.Value.settings.PrivacyMode)return;StackPanel body,actions;var w=Dialog("Notes et préparation de quête",out body,out actions,700);DofusToolsUi.Notes(body,actions,store,step,()=>w.Close(),()=>{Refresh();UpdateDofusOverlay();},Ink,Muted);ShowWindow(w);}

 void DofusPersonalInstructions(Panel panel,string source,string key){bool enabled=store.Value.instructions.companion;var controls=new WrapPanel();var companion=Btn("Style compagnon",()=>DofusChange(()=>store.Value.instructions.companion=true),enabled,!enabled);var original=Btn("Texte source",()=>DofusChange(()=>store.Value.instructions.companion=false),!enabled,enabled);controls.Children.Add(companion);controls.Children.Add(original);panel.Children.Add(controls);if(!enabled){panel.Children.Add(DofusPositionText(T(source,13,Ink,new Thickness(0,8,0,10))));return;}var adapted=CompanionInstructions.Read(store,DofusCompanion.Character(store.Value),source,key);panel.Children.Add(T(adapted.profile+" · à toi de jouer",11,Muted));foreach(var block in adapted.text.Split(new[]{"\n"},StringSplitOptions.RemoveEmptyEntries)){panel.Children.Add(DofusPositionText(T(block,13,Ink,new Thickness(0,5,0,10))));}panel.Children.Add(new Expander{Header="Lire le texte source complet",Foreground=Muted,Content=DofusPositionText(T(source,12,Muted,new Thickness(0,8,0,10))),Margin=new Thickness(0,4,0,8)});}

 System.Windows.Controls.TextBlock DofusPositionText(System.Windows.Controls.TextBlock text){return CoordinateLinks.Decorate(text,Accent,()=>!owner.IsPreview&&!store.Value.settings.PrivacyMode);}
 QuestInstructionIndex dofusInstructions;string dofusInstructionsRoot="";int dofusInstructionsVersion;
 QuestInstructionIndex DofusInstructionIndex {get{if(dofusInstructions==null||dofusInstructionsRoot!=store.Root){dofusInstructions=QuestInstructionIndex.Load(store);dofusInstructionsRoot=store.Root;}return dofusInstructions;}}
 string DofusInstructionSignature(){return dofusInstructionsVersion+"/"+dofusBusy+"/"+dofusMessage+"/"+WorkspaceNext.Hash(Encoding.UTF8.GetBytes(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(store.Value.instructions)));}
 void InvalidateDofusInstructions(){dofusInstructions=null;dofusInstructionsVersion++;}
 System.Windows.UIElement DofusInstructionPanel(TougliStep step){if(step==null||String.IsNullOrWhiteSpace(step.QuestId)||store.Value.settings.PrivacyMode)return null;var body=new StackPanel{Margin=new Thickness(0,14,0,8)};body.Children.Add(T("INSTRUCTIONS GANYMÈDE",11,Accent));var matches=DofusInstructionIndex.Match(step);if(matches.Count==0){body.Children.Add(T("Aucun extrait correspondant dans les guides chargés.",12,Muted));var load=Btn(dofusBusy?"Chargement…":"Charger les instructions du parcours",LoadDofusInstructions,false,true);load.IsEnabled=!dofusBusy;body.Children.Add(load);}else{string selection=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(step.QuestId+"/"+QuestInstructionIndex.NameKey(step.Title))),chosen;store.Value.instructions.sources.TryGetValue(selection,out chosen);var sources=matches.GroupBy(x=>x.GuideSlug).ToList();if(sources.Count==1)chosen=sources[0].Key;else{body.Children.Add(T("Plusieurs guides correspondent. Choisissez votre source.",11,Muted));var menu=Combo(new[]{"Choisir un guide…"}.Concat(sources.Select(g=>g.First().GuideTitle)),"Choisir un guide…");menu.SelectedIndex=Math.Max(0,sources.FindIndex(g=>g.Key==chosen)+1);menu.SelectionChanged+=delegate{if(menu.SelectedIndex>0)DofusChange(()=>store.Value.instructions.sources[selection]=sources[menu.SelectedIndex-1].Key);};body.Children.Add(menu);}var instructions=matches.Where(x=>x.GuideSlug==chosen).ToList();if(instructions.Count>0){string key=QuestInstructionIndex.CursorKey(store.Value,step,chosen),cursor;store.Value.instructions.cursors.TryGetValue(key,out cursor);int position=Math.Max(0,instructions.FindIndex(x=>x.Key==cursor));var entry=instructions[position];body.Children.Add(T(entry.GuideTitle+" · extrait "+(position+1)+" / "+instructions.Count,11,Muted));body.Children.Add(DofusPositionText(T(entry.Map+(entry.Coordinates==""?"":" · ["+entry.Coordinates+"]"),11,Accent)));DofusPersonalInstructions(body,entry.Details,entry.Key);body.Children.Add(T("Extrait propre à la quête. Trajets communs, illustrations et contexte complet dans la source. L’ordre reste celui de Tougli.",10,Muted));var buttons=new WrapPanel();var previous=Btn("← Instruction",()=>DofusInstructionCursor(key,instructions[Math.Max(0,position-1)].Key),false,true);previous.IsEnabled=position>0;buttons.Children.Add(previous);var next=Btn("Instruction →",()=>DofusInstructionCursor(key,instructions[Math.Min(instructions.Count-1,position+1)].Key),false,true);next.IsEnabled=position<instructions.Count-1;buttons.Children.Add(next);body.Children.Add(buttons);var links=new WrapPanel();if(entry.Coordinates!="")links.Children.Add(Btn("/travel Ganymède",()=>{if(!owner.IsPreview&&!store.Value.settings.PrivacyMode)Clipboard.SetText("/travel "+entry.Coordinates);},false,true));links.Children.Add(Btn("Voir l’étape source",()=>Open(entry.Url),false,true));body.Children.Add(links);body.Children.Add(T(entry.Credit,10,Muted));}}
 if(dofusBusy){body.Children.Add(T(dofusMessage,10,Muted));body.Children.Add(Btn("Annuler le chargement",()=>{if(dofusCancel!=null)dofusCancel.Cancel();},false,true));}return body;}
 void DofusInstructionCursor(string key,string value){if(store.Value.settings.PrivacyMode)return;DofusChange(()=>{var cursors=store.Value.instructions.cursors;if(!cursors.ContainsKey(key)&&cursors.Count>=5000)cursors.Remove(cursors.Keys.First());cursors[key]=value;});}
 void AssociateDofusInstructions(){if(store.Value.settings.PrivacyMode)return;StackPanel body,actions;var w=Dialog("Associer un guide Ganymède",out body,out actions,650);body.Children.Add(T("Les extraits du guide seront associés aux quêtes Tougli par nom exact normalisé. Cela ne change ni le parcours ni ses validations.",12,Muted));var input=new TextBox{MaxLength=250};Field(body,"Lien https://ganymede-app.com/guides/123 ou numéro",input);var error=T("",12,Accent);body.Children.Add(error);actions.Children.Add(Btn("Annuler",()=>w.Close(),false,true));actions.Children.Add(Btn("Associer",delegate{try{string slug=GanymedeReader.GuideSlug(input.Text);FinishFinanceDialog(w);DownloadDofusInstructions(slug);}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);}
 void DownloadDofusInstructions(string slug){if(store.Value.settings.PrivacyMode)return;DofusOperation(async(client,token)=>{var html=Encoding.UTF8.GetString(await client.Read(GanymedeReader.Url(slug),TougliReader.MaxBytes,token));var raw=GanymedeReader.Normalise(html);GanymedeReader.Parse(raw,slug);token.ThrowIfCancellationRequested();TougliReader.Cache(store,slug,raw);InvalidateDofusInstructions();dofusMessage="Guide Ganymède associé. Les extraits correspondants apparaissent sous vos quêtes Tougli.";});}
 void LoadDofusInstructions(){if(store.Value.settings.PrivacyMode)return;var doc=CurrentDofusDocument();if(doc==null)return;DofusOperation(async(client,token)=>{dofusCancel.CancelAfter(TimeSpan.FromMinutes(8));var catalogue=GanymedeReader.Catalogue(Encoding.UTF8.GetString(await client.Read(GanymedeReader.Site+"/tree?view=list",TougliReader.MaxBytes,token)));if(catalogue.Count==0)throw new InvalidDataException("Aucun guide principal français disponible.");int count=0,failures=0;foreach(var guide in catalogue){token.ThrowIfCancellationRequested();bool cached=false;try{cached=TougliReader.Cached(store,guide.Slug)!=null;}catch{}if(!cached){try{var html=Encoding.UTF8.GetString(await client.Read(GanymedeReader.Url(guide.Slug),TougliReader.MaxBytes,token));var raw=GanymedeReader.Normalise(html);GanymedeReader.Parse(raw,guide.Slug);token.ThrowIfCancellationRequested();TougliReader.Cache(store,guide.Slug,raw);}catch(OperationCanceledException){throw;}catch{failures++;}}count++;dofusMessage="Instructions Ganymède : "+count+" / "+catalogue.Count+" guides consultés"+(failures==0?"":" · "+failures+" indisponibles")+". Vos validations Tougli sont conservées.";InvalidateDofusInstructions();if(count%5==0||count==catalogue.Count){Refresh();UpdateDofusOverlay();}}int covered=doc.Steps.Count(s=>DofusInstructionIndex.Match(s).Any()),quests=doc.Steps.Count(s=>!String.IsNullOrEmpty(s.QuestId));dofusMessage=covered+" / "+quests+" étapes de quête avec extraits Ganymède pour "+doc.Title+"."+(failures==0?"":" "+failures+" guides indisponibles : relancez le chargement pour réessayer.");});}
}
